const $=s=>document.querySelector(s);
const menu=$('#menu-toggle');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));$('#site-links').classList.toggle('open',open);});
document.querySelectorAll('#site-links a').forEach(a=>a.addEventListener('click',()=>{$('#site-links').classList.remove('open');menu.setAttribute('aria-expanded','false');}));
const dialog=$('#contact-dialog');document.querySelectorAll('[data-contact]').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));$('#contact-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
$('#contact-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]'),status=$('#contact-status');button.disabled=true;status.textContent='Saving your inquiry…';try{const data=Object.fromEntries(new FormData(form));const response=await fetch('/api/partnerships',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:AbortSignal.timeout(20000)});const result=await response.json();if(!response.ok)throw Error(result.error||'Your inquiry could not be saved. Please retry.');form.reset();status.textContent='Your inquiry is saved for the GoPlan team. Reference: '+result.reference+'.';}catch(error){status.textContent=error.name==='TimeoutError'?'This is taking longer than expected. Please retry.':error.message;}finally{button.disabled=false;}});
